// Verify the Slack request signature before doing any paid/side-effecting work.
// Requires the webhook 'rawBody' option (set above) and $env.SLACK_SIGNING_SECRET.
const crypto = require('crypto');
const secret = $env.SLACK_SIGNING_SECRET;
if (!secret) throw new Error('SLACK_SIGNING_SECRET is not set');
const item = $input.first();
const headers = item.json.headers || {};
const sig = headers['x-slack-signature'];
const ts = headers['x-slack-request-timestamp'];
if (!sig || !ts) throw new Error('Missing Slack signature headers');
if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) throw new Error('Stale Slack request (possible replay)');
const raw = item.json.rawBody || JSON.stringify(item.json.body || {});
const base = `v0:${ts}:${raw}`;
const expected = 'v0=' + crypto.createHmac('sha256', secret).update(base).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(String(sig));
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Invalid Slack signature');
return [{ json: item.json.body || item.json }];
